#include "structures.hpp"

#include <algorithm>
#include <iostream>


void Edge::addKST(KST* kst) {
    KSTs.push_back(kst);
}

void Edge::removeKST(KST* kst) {
    auto it = std::find(KSTs.begin(), KSTs.end(), kst);
    if (it != KSTs.end()) {
        *it = KSTs.back();
        KSTs.pop_back();
    } else {
        std::cerr << "Error: KST not found in edge's KST list." << std::endl;
    }
}

//generated by AI
void KSTGenerator::generate(std::vector<std::unique_ptr<KST>>& out) {
    out_ = &out;
    const std::size_t m = adj_.rows(), n = adj_.columns();
    if (s_ == 0 || t_ == 0 || s_ > m || t_ > n) return;

    std::vector<std::size_t> allCols(n);
    for (std::size_t c = 0; c < n; ++c) allCols[c] = c;

    rows_.clear();
    rows_.reserve(s_);
    cols_.clear();
    cols_.reserve(t_);
    chooseRows(0, allCols);
}

//generated by AI
void KSTGenerator::chooseRows(std::size_t start, const std::vector<std::size_t>& common) {
    if (rows_.size() == s_) {
        chooseCols(common, 0);
        return;
    }
    const std::size_t m = adj_.rows();
    const std::size_t stillNeeded = s_ - rows_.size();

    std::vector<std::size_t> next;
    next.reserve(common.size());

    for (std::size_t r = start; r + stillNeeded <= m; ++r) {
        next.clear();
        for (std::size_t c : common)
            if (adj_(r, c).active) next.push_back(c);

        if (next.size() < t_) continue;     // prune

        rows_.push_back(r);
        chooseRows(r + 1, next);
        rows_.pop_back();
    }
}

//generated by AI
void KSTGenerator::chooseCols(const std::vector<std::size_t>& common, std::size_t start) {
    if (cols_.size() == t_) {
        emit();
        return;
    }
    const std::size_t stillNeeded = t_ - cols_.size();
    for (std::size_t i = start; i + stillNeeded <= common.size(); ++i) {
        cols_.push_back(common[i]);
        chooseCols(common, i + 1);
        cols_.pop_back();
    }
}

//generated by AI
void KSTGenerator::emit() {
    auto kst = std::make_unique<KST>();
    kst->id = nextId_++;
    kst->edges.reserve(s_ * t_);
    for (std::size_t r : rows_) {
        for (std::size_t c : cols_) {
            Edge* e = &adj_(r, c);
            kst->edges.push_back(e);
            e->addKST(kst.get());
        }
    }
    out_->push_back(std::move(kst));
}

//generated by AI
std::vector<std::unique_ptr<KST>> generateKSTs(Matrix<Edge>& adj, std::size_t s, std::size_t t, int firstId) {
    std::vector<std::unique_ptr<KST>> result;
    KSTGenerator g(adj, s, t, firstId);
    g.generate(result);
    return result;
}

KSTSet generateKSTs(int m, int n, int s, int t, int firstId) {
    KSTSet result(m, n);
    result.ksts = generateKSTs(result.adj, static_cast<std::size_t>(s),
                               static_cast<std::size_t>(t), firstId);
    return result;
}